      if (lookahead == '\\') SKIP(119);
      if (lookahead == ']') ADVANCE(234);
      if (lookahead == '^') ADVANCE(239);
      if (lookahead == '`') ADVANCE(298);
      if (lookahead == 'd') ADVANCE(331);
      if (lookahead == '{') ADVANCE(200);
      if (lookahead == '|') ADVANCE(215);
